type UserServiceHTTPClientImpl struct {
	cc *http.Client
}

func NewUserServiceHTTPClient(client *http.Client) UserServiceHTTPClient {
	return &UserServiceHTTPClientImpl{client}
}

// DeleteAddress 删除地址
//
// 原实现 AddressController::delete -> AddressLogic::delete($id, $userId)
//
//	$address = UserAddress::where(['id'=>$id, 'user_id'=>$userId])->find();
//	if (!$address) { self::setError('未找到地址记录'); return false; }
//	$address->delete();        // ⚠️ **硬删除**（表没有 delete_time 列）
//
// 控制器：`return $this->success('删除成功');` -> msg 是 "删除成功"，data 是空数组
// 校验 UserAddressDeleteValidate:
//
//	'id.require' => '地址记录ID不能为空'
//	'id.number'  => '地址记录ID不正确'
//
// 🔴🔴 **这是用 GET 做删除**（Route::get('address/delete', ...)）。
//
//	迁移时必须按写操作对待：写权限、幂等、以及被预取/爬虫误触发的风险。
//
// 需登录。
func (c *UserServiceHTTPClientImpl) DeleteAddress(ctx context.Context, in *DeleteAddressRequest, opts ...http.CallOption) (*DeleteAddressReply, error) {
	var out DeleteAddressReply
	pattern := "/v1/user/address/delete"
	path := binding.EncodeURL(pattern, in, true)
	opts = append(opts, http.Operation(OperationUserServiceDeleteAddress))
	opts = append(opts, http.PathTemplate(pattern))
	err := c.cc.Invoke(ctx, "GET", path, nil, &out, opts...)
	if err != nil {
		return nil, err
	}
	return &out, nil
}

// GetAddressDefault 用户默认地址
//
// 原实现 v1/user/AddressController::addressDefault -> AddressLogic::addressDefault($params,$userId)
//
//	$cacheKey = "purchase:addressDefault:$userId";   // ⚠️ 名字带 purchase，与采购无关
//	$fields = "id,is_default,address";               // ⚠️ 只返回这三列
//	带 id -> where(user_id,id)；否则先查 is_default=1，没有则 order(id asc) 取第一条
//	都找不到 -> setError('未找到地址记录') -> fail
//
// ⚠️ 控制器用的是 `$this->success('成功', $result)` —— **不是 data()**，
//
//	所以 msg 是 "成功" 而不是空串（见 Envelope 实现）。
//
// 需登录（AddressController 未声明 $notNeedLogin）。
func (c *UserServiceHTTPClientImpl) GetAddressDefault(ctx context.Context, in *GetAddressDefaultRequest, opts ...http.CallOption) (*GetAddressDefaultReply, error) {
	var out GetAddressDefaultReply
	pattern := "/v1/user/address/default"
	path := binding.EncodeURL(pattern, in, true)
	opts = append(opts, http.Operation(OperationUserServiceGetAddressDefault))
	opts = append(opts, http.PathTemplate(pattern))
	err := c.cc.Invoke(ctx, "GET", path, nil, &out, opts...)
	if err != nil {
		return nil, err
	}
	return &out, nil
}

// GetAddressList 地址列表（分页）
//
// 原实现 v1/user/AddressController::index -> $this->dataLists(new AddressLists())
//
//	UserAddress::hasWhere('app', ['UserAddress.user_id'=>$userId],
//	    'App.name platform_name,App.flag,UserAddress.id,UserAddress.contact_user,
//	     UserAddress.contact_phone,UserAddress.address,UserAddress.fettle,UserAddress.is_default')
//
// ⚠️ hasWhere 生成的是 **INNER JOIN**（app 关联是 hasOne(App::class,'id','app_id')）：
//
//	FROM x_user_address UserAddress
//	INNER JOIN x_app App ON App.id = UserAddress.app_id
//	WHERE UserAddress.user_id = ?
//	app_id 在 x_app 里不存在的地址**不会出现**，count() 用的也是同一个 JOIN。
//
// 用 RawData（行的键是 DB 列名 + App 的别名 platform_name）。
// 需登录。
func (c *UserServiceHTTPClientImpl) GetAddressList(ctx context.Context, in *GetAddressListRequest, opts ...http.CallOption) (*RawData, error) {
	var out RawData
	pattern := "/v1/user/address"
	path := binding.EncodeURL(pattern, in, true)
	opts = append(opts, http.Operation(OperationUserServiceGetAddressList))
	opts = append(opts, http.PathTemplate(pattern))
	err := c.cc.Invoke(ctx, "GET", path, nil, &out, opts...)
	if err != nil {
		return nil, err
	}
	return &out, nil
}

// GetMessageDetail 消息详情
//
// 原实现 MessageController::detail -> MessageLogic::detail($userId,$params)
// 校验用 MessageIdValidate 的 ->get()，规则同 setOneRead（require|integer|gt:0）
//
//	INNER JOIN messages_body mb ON m.message_id = mb.id
//	where: m.message_id = id AND m.recv_id = userId AND m.is_del = 0
//	找不到 -> "消息不存在或无权查看"
//	自动标已读：if (is_read == 0) Messages::where('id', $messageId)->update([...])
//	最后加计算列 type_name = TypeEnum::getTypeDesc(type)
//
// 🔴 自动标已读那句用的是**主键 id**，而查询按 **message_id** —— 同一个变量两种语义，
//
//	是原项目的 bug。按"不改动原项目逻辑"照搬，详见 biz/message_detail.go。
//
// 用 RawData：11 个键混来自两张表，且 create_time 未重新格式化。
func (c *UserServiceHTTPClientImpl) GetMessageDetail(ctx context.Context, in *GetMessageDetailRequest, opts ...http.CallOption) (*RawData, error) {
	var out RawData
	pattern := "/v1/user/message/detail"
	path := binding.EncodeURL(pattern, in, true)
	opts = append(opts, http.Operation(OperationUserServiceGetMessageDetail))
	opts = append(opts, http.PathTemplate(pattern))
	err := c.cc.Invoke(ctx, "GET", path, nil, &out, opts...)
	if err != nil {
		return nil, err
	}
	return &out, nil
}

